async function handleListSessions(
  ws: WebSocket,
  userId: string | number,
  sessionStore: SessionStore | undefined,
  options: SessionListOptions
): Promise<void> {
  if (!sessionStore?.listFor) return sendJson(ws, {type: 'session_list', sessions: []});
  try {
    const summaries = await sessionStore.listFor(userId, options);
    sendJson(ws, {
      type: 'session_list',
      sessions: summaries.map(({sessionId, createdAt, updatedAt, entryCount}) => ({
        sessionId,
        createdAt: createdAt.toISOString(),
        updatedAt: updatedAt.toISOString(),
        entryCount,
      })),
    });
  } catch (error) {
    log.error('ws', 'listing conversations failed', {
      userId,
      error: error instanceof Error ? error.message : 'Unknown error',
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}""",1)
